$ErrorActionPreference='Stop';Set-Location $PSScriptRoot;New-Item -ItemType Directory -Force backups|Out-Null;$stamp=(Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssZ');$tmp=Join-Path $env:TEMP ('atlas-'+$stamp);New-Item -ItemType Directory $tmp|Out-Null;try{docker compose exec -T atlas node -e "const D=require('better-sqlite3');const d=new D('/data/atlas.sqlite',{readonly:true});d.backup('/tmp/atlas.sqlite').then(()=>d.close()).catch(e=>{console.error(e);process.exit(1)})";docker cp atlas-forex-replay:/tmp/atlas.sqlite (Join-Path $tmp 'atlas.sqlite');docker cp atlas-forex-replay:/data/market $tmp 2>$null;docker cp atlas-forex-replay:/data/screenshots $tmp 2>$null;Compress-Archive -Path (Join-Path $tmp '*') -DestinationPath (Join-Path $PSScriptRoot ("backups/atlas-"+$stamp+'.zip'));Write-Host 'Backup created'}finally{Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue}
